{
  "type": "object",
  "properties": {
    "ctl00_body_txtName": {
      "type": "string",
      "description": "Corporate Title Name (e.g., 'Middle Management')."
    },
    "ctl00_body_dpSalary": {
      "type": "string",
      "description": "Selected Salary Grade code (e.g., '000005'). All Salary Grades data for getUpdateCorporateTitleDetails api will be displayed for the user to select, and the corresponding value must be picked."
    },
    "ctl00_body_chkTop": {
      "type": "string",
      "enum": ["on"],
      "description": "Top in Hierarchy flag. If provided as 'on', 'Next Upgrade Level' must NOT be passed."
    },
    "ctl00_body_dpNextUpgrade": {
      "type": "string",
      "description": "Next Upgrade Level code (e.g., '000008'). This must be provided if 'Top in Hierarchy' is not 'on'. and user off to display the all next upgrade level detaisl for retrive the data for getUpdateCorporateTitleDetails api"
    },
    "ctl00_body_nuLevel": {
      "type": "integer",
      "description": "Level number (e.g., 3)."
    },
    "ctl00_body_ManagePos": {
      "type": "string",
      "enum": ["on", "off"],
      "description": "Indicates whether it is a Managerial Position. on or off"
    }
  },
  "required": [
    "ctl00_body_txtName",
    "ctl00_body_dpSalary",
    "ctl00_body_nuLevel"
  ],
  "dependencies": {
    "ctl00_body_chkTop": {
      "oneOf": [
        {
          "properties": {
            "ctl00_body_chkTop": {
              "const": "on"
            }
          },
          "not": {
            "required": ["ctl00_body_dpNextUpgrade"]
          }
        },
        {
          "not": {
            "required": ["ctl00_body_chkTop"]
          },
          "required": ["ctl00_body_dpNextUpgrade"]
        }
      ]
    }
  }
}

basic.transformer:
(async function (data, args, reqOptions) {
  const myHeaders = new Headers();
  myHeaders.append("accept", "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.7");
  myHeaders.append("accept-language", "en-US,en;q=0.9");

  const urlencoded = new URLSearchParams();
  urlencoded.append("scrollLeft", "0");
  urlencoded.append("scrollTop", "0");
  urlencoded.append("__EVENTTARGET", "");
  urlencoded.append("__EVENTARGUMENT", "");
  urlencoded.append("__VIEWSTATE", window.cp.viewState);
  urlencoded.append("__VIEWSTATEGENERATOR", window.cp.viewStateGen);
  urlencoded.append("__VIEWSTATEENCRYPTED", "");
  urlencoded.append("__EVENTVALIDATION", window.cp.eventValidation);
  urlencoded.append("ctl00$hdnDateFormat", "dd/mm/yy");

  urlencoded.append(
    "ctl00$body$txtName",
    args["ctl00_body_txtName"]
  );

  urlencoded.append(
    "ctl00$body$dpSalary",
    args["ctl00_body_dpSalary"]
  );

  if (args["ctl00_body_chkTop"] === "on") {
    urlencoded.append("ctl00$body$chkTop", "on");
  } else {
    urlencoded.append(
      "ctl00$body$dpNextUpgrade",
      args["ctl00_body_dpNextUpgrade"] || "-1"
    );
  }

  urlencoded.append(
    "ctl00$body$nuLevel",
    args["ctl00_body_nuLevel"]?.toString() || ""
  );

  urlencoded.append("ctl00$body$butSave", "Save");

  const requestOptions = {
    method: "POST",
    headers: myHeaders,
    body: urlencoded,
    redirect: "follow"
  };

  const response = await fetch(
    `${location.origin}/hr/EIM/CorporeteTitle.aspx`,
    requestOptions
  );

  const html = await response.text();

  return "Created successfully!!";
})

